def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Ensure y_true is a 1D tensor with integer class labels
    if K.ndim(y_true) == 2 and K.shape(y_true)[1] == 1:
        y_true = K.flatten(y_true)  # Convert from (num_samples, 1) to (num_samples,)

    # Get the maximum class index from y_true
    y_true = K.cast(y_true, 'int32')

    # Use in_top_k to check if the true labels are in the top k predictions
    return K.mean(K.in_top_k(y_pred, y_true, k), axis=-1)
