def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Ensure y_true is in the right format (int32)
    y_true = K.cast(y_true, 'int32')  # Assumes y_true are integer labels

    # Check for correct shape
    if K.ndim(y_true) == 2:
        y_true = K.argmax(y_true, axis=-1)  # Convert from one-hot to indices

    return K.mean(K.in_top_k(y_pred, y_true, k), axis=-1)
