def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Ensure y_true is of the correct shape and type
    if K.ndim(y_true) == 2:
        y_true = K.argmax(y_true, axis=-1)  # Convert from one-hot to sparse format

    # Ensure y_true is cast to int32 (it should contain class indices)
    y_true = K.cast(y_true, 'int32')

    # Use K.in_top_k to calculate top-k categorical accuracy
    return K.mean(K.in_top_k(y_pred, y_true, k), axis=-1)
