def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Ensure y_true is in the right format (e.g., casting to int32 for categorical indices)
    if K.ndim(y_true) == 2:
        y_true = K.argmax(y_true, axis=-1)  # Convert from one-hot to integer class labels
    elif K.ndim(y_true) != 1:
        raise ValueError("y_true should be a 1D or 2D array (one-hot encoded).")

    y_true = K.cast(y_true, 'int32')  # Ensure y_true is int32
    return K.mean(K.in_top_k(y_pred, y_true, k), axis=-1)
```

