def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Ensure y_true is correctly interpreted as indices
    if K.ndim(y_true) == 2:
        y_true = K.argmax(y_true, axis=-1)  # convert one-hot to indices

    # Ensure y_true is the correct type and shape
    y_true = K.cast(y_true, 'int32')

