```python
def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Ensure y_true is in the correct format (1D tensor of integer indices)
    if K.ndim(y_true) == 2:
        y_true = K.argmax(y_true, axis=-1)  # Convert from one-hot to class indices if needed
    y_true = K.cast(y_true, 'int32')  # Cast to int32 for proper indexing

    # Calculating the top-k categorical accuracy
    return K.mean(K.in_top_k(y_pred, y_true, k), axis=-1)
```
